local cache,failed,loading={},{},{}
local function ext(data,url)
 if data:sub(1,8)=="\137PNG\r\n\26\n" then return ".png" end
 if data:sub(1,3)=="\255\216\255" then return ".jpg" end
 if data:sub(1,4)=="OggS" then return ".ogg" end
 if data:sub(1,4)=="RIFF" then return ".wav" end
 if data:sub(1,3)=="ID3" or url:match("%.mp3$") then return ".mp3" end
 return ".bin"
end
local function download(url,key)
 local ok,d=pcall(function() return game:HttpGet(url) end)
 if not ok or type(d)~="string" or #d<50 then return nil end
 local file="edge_oblivion_"..key..ext(d,url)
 if not pcall(function() writefile(file,d) end) then return nil end
 local yes,asset=pcall(function() return G(file) end)
 if yes then return asset end
 return nil
end
local function asset(idx)
 if cache[idx] then return cache[idx] end
 if failed[idx] or loading[idx] then return nil end
 loading[idx]=true
 local a=download(U[idx],tostring(idx))
 loading[idx]=nil
 if a then cache[idx]=a else failed[idx]=true end
 return a
end
local function idOf(v)
 if type(v)~="string" then return nil end
 return v:match("(%d+)")
end
local function field(o)
 if o:IsA("ImageLabel") or o:IsA("ImageButton") then return "Image" end
 if o:IsA("Decal") or o:IsA("Texture") or o:IsA("ParticleEmitter") or o:IsA("Trail") or o:IsA("Beam") then return "Texture" end
 if o:IsA("MeshPart") then return "TextureID" end
 if o:IsA("SpecialMesh") then return "TextureId" end
 if o:IsA("Sound") then return "SoundId" end
 if o:IsA("Shirt") then return "ShirtTemplate" end
 if o:IsA("Pants") then return "PantsTemplate" end
 if o:IsA("ShirtGraphic") then return "Graphic" end
 return nil
end
local jobs,seen={},{}
local function inspect(o)
 if not state.running then return end
 local p=field(o)
 if not p then return end
 local ok,v=pcall(function() return o[p] end)
 if not ok then return end
 local id=idOf(v)
 local n=id and M[id]
 if not n then return end
 if seen[o] and seen[o][p]==n then return end
 seen[o]=seen[o] or {};seen[o][p]=n
 jobs[#jobs+1]={o,p,n}
end
-- Scan first, then progressively download only assets actually used.
task.spawn(function()
 for i,o in ipairs(game:GetDescendants()) do
  if not state.running then return end
  inspect(o)
  if i%250==0 then task.wait() end
 end
end)
game.DescendantAdded:Connect(function(o)
 if not state.running then return end
 task.defer(function()
  inspect(o)
  task.wait(.25)
  if o.Parent then inspect(o) end
 end)
end)
task.spawn(function()
 local head=1
 while state.running do
  local count=0
  while head<=#jobs and count<8 do
   local j=jobs[head];head=head+1;count=count+1
   local o,p,n=j[1],j[2],j[3]
   if o and o.Parent then
    local a=asset(n)
    if a then pcall(function() o[p]=a end) end
   end
  end
  task.wait(.1)
 end
end)
-- Station SeamSafe V4 Stars: six-face fresh-sky override.
task.spawn(function()
 local A={}
 for _,f in ipairs({"Bk","Dn","Ft","Lf","Rt","Up"}) do
  A[f]=download(S[f],"station_sky_"..f)
  if not A[f] then warn("[EDGE] Sky face failed: "..f) return end
 end
 local busy=false
 local function fresh()
  if not state.running or busy then return end
  busy=true
  for _,o in ipairs(L:GetChildren()) do
   if o:IsA("Sky") then pcall(function() o:Destroy() end) end
  end
  local s=Instance.new("Sky")
  s.Name="EdgeOblivionFreshSky"
  s.SkyboxBk=A.Bk;s.SkyboxDn=A.Dn;s.SkyboxFt=A.Ft
  s.SkyboxLf=A.Lf;s.SkyboxRt=A.Rt;s.SkyboxUp=A.Up
  s.Parent=L
  busy=false
 end
 fresh()
 for _,t in ipairs({.5,1.5,3,6,10}) do task.delay(t,fresh) end
 local last=0
 L.ChildAdded:Connect(function(o)
  if not state.running then return end
  if o:IsA("Sky") and o.Name~="EdgeOblivionFreshSky" then
   local now=os.clock()
   if now-last>.5 then last=now;task.delay(.15,fresh) end
  end
 end)
end)
pcall(function()
 SG:SetCore("SendNotification",{Title="Edge of Oblivion",Text="Adaptive pack started; assets load as needed",Duration=6})
end)
